      hu: ["Kr. e. 12000 - Kr. u. 100 k\\u00f6z\\u00f6tti m\\u0171v\\u00e9szet.", "Zsir\\u00e1fokat \\u00e9s elef\\u00e1ntokat \\u00e1br\\u00e1zol.", "UNESCO vil\\u00e1g\\u00f6r\\u00f6ks\\u00e9g."],
      ro: ["Art\\u0103 din 12.000 \\u00ee.Hr. p\\u00e2n\\u0103 \\u00een 100 d.Hr.", "Arat\\u0103 girafe \\u0219i elefan\\u021bi.", "Patrimoniu Mondial UNESCO."],
