      hu: ["Eredete a 12. sz\\u00e1zadra ny\\u00falik vissza.", "21 k\\u00fap alak\\u00fa kupol\\u00e1ja van.", "V\\u00e1lyogt\\u00e9gl\\u00e1b\\u00f3l \\u00e9p\\u00fclt."],
      ro: ["Originar\\u0103 din secolul al XII-lea.", "Are 21 de cupole conice.", "F\\u0103cut\\u0103 din c\\u0103r\\u0103mizi de noroi."],
      en: ["Origins in the 12th century.", "Has 21 conical domes.", "Made of mudbrick."]
